import { readFileSync } from 'node:fs';
import { createHash } from 'node:crypto';
import { quote, dialect } from './sql.js';
const base = new URL('../../../migrations/postgres/', import.meta.url);
const raw = readFileSync(new URL('0001-baseline.json',base));
const events = readFileSync(new URL('0001-game-events.sql',base),'utf8');
const definition = JSON.parse(raw.toString());
// The baseline JSON, explicit trigger SQL AND executable migration implementation
// are immutable once applied. Any later structural change needs a new version.
const implementation = readFileSync(new URL('./migrations.js',import.meta.url),'utf8').replace(/\r\n/g,'\n').replace(/^\/\/# sourceMappingURL=.*$/gm,'').trim();
export const checksum = createHash('sha256').update(JSON.stringify(definition)).update(events.replace(/\r\n/g,'\n')).update(implementation).digest('hex');
export const version = '0001';
export async function metadata(client: any) {
  await client.query(`CREATE SCHEMA IF NOT EXISTS gtt_meta;
    CREATE TABLE IF NOT EXISTS gtt_meta.schema_migrations(namespace text NOT NULL,version text NOT NULL,checksum text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(namespace,version));
    CREATE TABLE IF NOT EXISTS gtt_meta.imports(namespace text PRIMARY KEY,source_sha256 text NOT NULL,report jsonb NOT NULL,completed_at timestamptz NOT NULL DEFAULT now());`);
}
export async function ensureSchema(client: any, schema: string, kind: string) {
  if(!/^[a-z][a-z0-9_]{0,62}$/.test(schema)||!definition.kinds[kind])throw Error('Invalid migration namespace or kind');
  await client.query('BEGIN');
  try {
    await client.query('SELECT pg_advisory_xact_lock(741104,hashtext($1))',[schema]);
    const applied=(await client.query('SELECT checksum FROM gtt_meta.schema_migrations WHERE namespace=$1 AND version=$2',[schema,version])).rows[0];
    if(applied) {
      if(applied.checksum!==checksum)throw Error('Applied migration checksum changed: '+schema);
      await client.query('COMMIT');return;
    }
    if((await client.query('SELECT 1 FROM pg_namespace WHERE nspname=$1',[schema])).rows.length)throw Error('Refusing existing unmanaged namespace '+schema);
    await client.query('CREATE SCHEMA '+quote(schema));
    await client.query('SET LOCAL search_path TO '+quote(schema)+',pg_catalog');
    const tables=Object.values(definition.kinds[kind]) as any[];
    for(const table of tables) {
      const sql=dialect(table.sql)
        .replace(/\bINTEGER PRIMARY KEY(?: AUTOINCREMENT)?/gi,'BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY')
        .replace(/\bINTEGER\b/gi,'BIGINT').replace(/\bBLOB\b/gi,'BYTEA')
        .replace(/\s+REFERENCES\s+["\w]+\s*\([^)]*\)(?:\s+ON DELETE\s+(?:CASCADE|SET NULL|RESTRICT|NO ACTION))?/gi,'');
      await client.query(sql);
    }
    for(const table of tables) {
      for(const index of table.indexes)await client.query(dialect(index.sql));
      const groups=new Map<number,any[]>();
      for(const fk of table.foreignKeys)groups.set(fk.id,[...(groups.get(fk.id)??[]),fk]);
      for(const [id,keys] of groups) {
        keys.sort((a,b)=>a.seq-b.seq);const fk=keys[0];
        await client.query(`ALTER TABLE ${quote(table.name)} ADD CONSTRAINT ${quote(table.name+'_fk_'+id)} FOREIGN KEY (${keys.map(k=>quote(k.from)).join(',')}) REFERENCES ${quote(fk.table)}(${keys.map(k=>quote(k.to)).join(',')}) ON UPDATE ${fk.on_update} ON DELETE ${fk.on_delete} DEFERRABLE INITIALLY DEFERRED`);
      }
    }
    if(kind==='game')await client.query(events);
    await client.query('INSERT INTO gtt_meta.schema_migrations(namespace,version,checksum) VALUES($1,$2,$3)',[schema,version,checksum]);
    await client.query('COMMIT');
  } catch(e) {await client.query('ROLLBACK');throw e;}
}
